const zerv = @import("zerv");

pub fn main() !void {
  const allocator = gpa.allocator();
  var gpa = std.heap.GeneralPurposeAllocator(.{}){};

  // In more advance cases,
  // a custom “Handler” will be used instead of “void”.
  // The last parameter is the handler instance,
  // since the handler is “void”,
  // the value void ({}) is passed.
  var server = try zerv.Server(void).init(allocator, .{.port = 5882}, {});
  defer {
    // clean shutdown, finishes serving any live request
    server.stop();
    server.deinit();
  }

  var router = server.router(.{});
  router.get("/api/user/:id", getUser, .{});

  // blocks
  try server.listen(); 
}

fn getUser(req: *zerv.Request, res: *zerv.Response) !void {
  res.status = 200;
  try res.json(.{.id = req.param("id").?, .name = "Teg"}, .{});
}
```

# Examples
See the [examples](https://github.com/pchchv/zerv/tree/master/examples) folder for examples. If you clone this repository, you can run `zig build example_#` to run a specific example:

```bash
$ zig build example_1
listening http://localhost:8800/
```

# Installation
1) Add zerv as a dependency in your `build.zig.zon`:

```bash
zig fetch --save git+https://github.com/pchchv/zerv#master
```

2) In your `build.zig`, add the `zerv` module as a dependency you your program:

```zig
const zerv = b.dependency("zerv", .{
    .target = target,
    .optimize = optimize,
});

// the executable from your call to b.addExecutable(...)
exe.root_module.addImport("zerv", zerv.module("zerv"));
```

## Why not std.http.Server
`std.http.Server` is very slow and assumes well-behaved clients.

There are many implementations of the Zig HTTP server. Most of them bypass `std.http.Server` and tend to be slow. Benchmarks will help to verify this.  It should be canceled that some wrap C libraries and run faster.  

zerv is written in Zig, without using `std.http.Server`. On M2, a basic request can reach 140K requests per second.

# Handler
When a non-void Handler is used, the value given to `Server(H).init` is passed to every action. This is how application-specific data can be passed into your actions.

```zig
const pg = @import("pg");
const std = @import("std");
const zerv = @import("zerv");

pub fn main() !void {
  var gpa = std.heap.GeneralPurposeAllocator(.{}){};
  const allocator = gpa.allocator();

  var db = try pg.Pool.init(allocator, .{
    .connect = .{ .port = 5432, .host = "localhost"},
    .auth = .{.username = "user", .database = "db", .password = "pass"}
  });
  defer db.deinit();

  var app = App{
    .db = db,
  };

  var server = try zerv.Server(*App).init(allocator, .{.port = 5882}, &app);
  var router = server.router(.{});
  router.get("/api/user/:id", getUser, .{});
  try server.listen();
}

const App = struct {
    db: *pg.Pool,
};

fn getUser(app: *App, req: *zerv.Request, res: *zerv.Response) !void {
  const user_id = req.param("id").?;

  var row = try app.db.row("select name from users where id = $1", .{user_id}) orelse {
    res.status = 404;
    res.body = "Not found";
    return;
  };
  defer row.deinit() catch {};

  try res.json(.{
    .id = user_id,
    .name = row.get([]u8, 0),
  }, .{});
}
```

## Custom Dispatch
Beyond sharing state, your custom handler can be used to control how zerv behaves. By defining a public `dispatch` method you can control how (or even **if**) actions are executed. For example, to log timing, you could do:

```zig
const App = struct {
  pub fn dispatch(self: *App, action: zerv.Action(*App), req: *zerv.Request, res: *zerv.Response) !void {
    var timer = try std.time.Timer.start();

    // your `dispatch` doesn't _have_ to call the action
    try action(self, req, res);

    const elapsed = timer.lap() / 1000; // ns -> us
    std.log.info("{} {s} {d}", .{req.method, req.url.path, elapsed});
  }
};
```

### Per-Request Context
The 2nd parameter, `action`, is of type `zerv.Action(*App)`. This is a function pointer to the function you specified when setting up the routes. As we've seen, this works well to share global data. But, in many cases, you'll want to have request-specific data.

Consider the case where you want your `dispatch` method to conditionally load a user (maybe from the `Authorization` header of the request). How would you pass this `User` to the action? You can't use the `*App` directly, as this is shared concurrently across all requests.

To achieve this, we'll add another structure called `RequestContext`. You can call this whatever you want, and it can contain any fields of methods you want.

```zig
const RequestContext = struct {
  // You don't have to put a reference to your global data.
  // But chances are you'll want.
  app: *App,
  user: ?User,
};
```

We can now change the definition of our actions and `dispatch` method:

```zig
fn getUser(ctx: *RequestContext, req: *zerv.Request, res: *zerv.Response) !void {
   // can check if ctx.user is != null
}

const App = struct {
  pub fn dispatch(self: *App, action: zerv.Action(*RequestContext), req: *zerv.Request, res: *zerv.Response) !void {
    var ctx = RequestContext{
      .app = self,
      .user = self.loadUser(req),
    }
    return action(&ctx, req, res);
  }

  fn loadUser(self: *App, req: *zerv.Request) ?User {
    // todo, maybe using req.header("authorizaation")
  }
};

```

zerv infers the type of the action based on the 2nd parameter of your handler's `dispatch` method. If you use a `void` handler or your handler doesn't have a `dispatch` method, then you won't interact with `zerv.Action(H)` directly.

## Not Found
If your handler has a public `notFound` method, it will be called whenever a path doesn't match a found route:

```zig
const App = struct {
  pub fn notFound(_: *App, req: *zerv.Request, res: *zerv.Response) !void {
    std.log.info("404 {} {s}", .{req.method, req.url.path});
    res.status = 404;
    res.body = "Not Found";
  }
};
```

## Error Handler
If your handler has a public `uncaughtError` method, it will be called whenever there's an unhandled error. This could be due to some internal zerv bug, or because your action return an error. 

```zig
const App = struct {
  pub fn uncaughtError(self: *App, _: *Request, res: *Response, err: anyerror) void {
    std.log.info("500 {} {s} {}", .{req.method, req.url.path, err});
    res.status = 500;
    res.body = "sorry";
  }
};
```

Notice that, unlike `notFound` and other normal actions, the `uncaughtError` method cannot return an error itself.

## Takeover
For the most control, you can define a `handle` method. This circumvents most of zerv's dispatching, including routing. Frameworks like JetZig hook use `handle` in order to provide their own routing and dispatching. When you define a `handle` method, then any `dispatch`, `notFound` and `uncaughtError` methods are ignored by zerv.

```zig
const App = struct {
  pub fn handle(app: *App, req: *Request, res: *Response) void {
    // todo
  }
};
```

The behavior `zerv.Server(H)` is controlled by 
The library supports both simple and complex use cases. A simple use case is shown below. It's initiated by the call to `zerv.Server()`:

```zig
const std = @import("std");
const zerv = @import("zerv");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const allocator = gpa.allocator();

    var server = try zerv.Server().init(allocator, .{.port = 5882});

    // overwrite the default notFound handler
    server.notFound(notFound);

    // overwrite the default error handler
    server.errorHandler(errorHandler); 

    var router = server.router(.{});

    // use get/post/put/head/patch/options/delete
    // you can also use "all" to attach to all methods
    router.get("/api/user/:id", getUser, .{});

    // start the server in the current thread, blocking.
    try server.listen(); 
}

fn getUser(req: *zerv.Request, res: *zerv.Response) !void {
    // status code 200 is implicit. 

    // The json helper will automatically set the res.content_type = zerv.ContentType.JSON;
    // Here we're passing an inferred anonymous structure, but you can pass anytype 
    // (so long as it can be serialized using std.json.stringify)

    try res.json(.{.id = req.param("id").?, .name = "Teg"}, .{});
}

fn notFound(_: *zerv.Request, res: *zerv.Response) !void {
    res.status = 404;

    // you can set the body directly to a []u8, but note that the memory
    // must be valid beyond your handler. Use the res.arena if you need to allocate
    // memory for the body.
    res.body = "Not Found";
}

// note that the error handler return `void` and not `!void`
fn errorHandler(req: *zerv.Request, res: *zerv.Response, err: anyerror) void {
    res.status = 500;
    res.body = "Internal Server Error";
    std.log.warn("zerv: unhandled exception for request: {s}\nErr: {}", .{req.url.raw, err});
}
```

# Memory and Arenas
Any allocations made for the response, such as the body or a header, must remain valid until **after** the action returns. To achieve this, use `res.arena` or the `res.writer()`:

```zig
fn arenaExample(req: *zerv.Request, res: *zerv.Response) !void {
    const query = try req.query();
    const name = query.get("name") orelse "stranger";
    res.body = try std.fmt.allocPrint(res.arena, "Hello {s}", .{name});
}

fn writerExample(req: *zerv.Request, res: *zerv.Response) !void {
    const query = try req.query();
    const name = query.get("name") orelse "stranger";
    try std.fmt.format(res.writer(), "Hello {s}", .{name});
}
```

Alternatively, you can explicitly call `res.write()`. Once `res.write()` returns, the response is sent and your action can cleanup/release any resources.

`res.arena` is actually a configurable-sized thread-local buffer that fallsback to an `std.heap.ArenaAllocator`. In other words, it's fast so it should be your first option for data that needs to live only until your action exits.

# zerv.Request
The following fields are the most useful:

* `method` - an zerv.Method enum
* `arena` - A fast thread-local buffer that fallsback to an ArenaAllocator, same as `res.arena`.
* `url.path` - the path of the request (`[]const u8`)
* `address` - the std.net.Address of the client

If you give your route a `data` configuration, the value can be retrieved from the optional `route_data` field of the request.

## Path Parameters
The `param` method of `*Request` returns an `?[]const u8`. For example, given the following path:

```zig
router.get("/api/users/:user_id/favorite/:id", user.getFavorite, .{});
```

Then we could access the `user_id` and `id` via:

```zig
pub fn getFavorite(req *http.Request, res: *http.Response) !void {
    const user_id = req.param("user_id").?;
    const favorite_id = req.param("id").?;
    ...
```

In the above, passing any other value to `param` would return a null object (since the route associated with `getFavorite` only defines these 2 parameters). Given that routes are generally statically defined, it should not be possible for `req.param` to return an unexpected null. However, it *is* possible to define two routes to the same action:

```zig
router.put("/api/users/:user_id/favorite/:id", user.updateFavorite, .{});

// currently logged in user, maybe?
router.put("/api/use/favorite/:id", user.updateFavorite, .{});
```

In which case the optional return value of `param` might be useful.

## Header Values
Similar to `param`, header values can be fetched via the `header` function, which also returns a `?[]const u8`:

```zig
if (req.header("authorization")) |auth| {

} else { 
    // not logged in?:
}
```

Header names are lowercase. Values maintain their original casing.

To iterate over all headers, use:

```zig
var it = req.headers.iterator();
while (it.next()) |kv| {
  // kv.key
  // kv.value
}
```

## QueryString
The framework does not automatically parse the query string. Therefore, its API is slightly different.

```zig
const query = try req.query();
if (query.get("search")) |search| {

} else {
    // no search parameter
};
```

On first call, the `query` function attempts to parse the querystring. This requires memory allocations to unescape encoded values. The parsed value is internally cached, so subsequent calls to `query()` are fast and cannot fail.

The original casing of both the key and the name are preserved.

To iterate over all query parameters, use:

```zig
var it = req.query().iterator();
while (it.next()) |kv| {
  // kv.key
  // kv.value
}
```

## Body
The body of the request, if any, can be accessed using `req.body()`. This returns a `?[]const u8`.

### Json Body
The `req.json(TYPE)` function is a wrapper around the `body()` function which will call `std.json.parse` on the body. This function does not consider the content-type of the request and will try to parse any body.

```zig
if (try req.json(User)) |user| {

}
```

### JsonValueTree Body
The `req.jsonValueTree()` function is a wrapper around the `body()` function which will call `std.json.Parse` on the body, returning a `!?std.jsonValueTree`. This function does not consider the content-type of the request and will try to parse any body.

```zig
if (try req.jsonValueTree()) |t| {
    // probably want to be more defensive than this
    const product_type = r.root.Object.get("type").?.String;
    //...
}
```

### JsonObject Body
The even more specific `jsonObject()` function will return an `std.json.ObjectMap` provided the body is a map

```zig
if (try req.jsonObject()) |t| {
    // probably want to be more defensive than this
    const product_type = t.get("type").?.String;
    //...
}
```

## Form Data
The body of the request, if any, can be parsed as a "x-www-form-urlencoded "value  using `req.formData()`. The `request.max_form_count` configuration value must be set to the maximum number of form fields to support. This defaults to 0.

This behaves similarly to `query()`.

On first call, the `formData` function attempts to parse the body. This can require memory allocations to unescape encoded values. The parsed value is internally cached, so subsequent calls to `formData()` are fast and cannot fail.

The original casing of both the key and the name are preserved.

To iterate over all fields, use:

```zig
var it = (try req.formData()).iterator();
while (it.next()) |kv| {
  // kv.key
  // kv.value
}
```

Once this function is called, `req.multiFormData()` will no longer work (because the body is assumed parsed).

## Multi Part Form Data
Similar to the above, `req.multiFormData()` can be called to parse requests with a "multipart/form-data" content type. The `request.max_multiform_count` configuration value must be set to the maximum number of form fields to support. This defaults to 0.

This is a different API than `formData` because the return type is different. Rather than a simple string=>value type, the multi part form data value consists of a `value: []const u8` and a `filename: ?[]const u8`.

On first call, the `multiFormData` function attempts to parse the body. The parsed value is internally cached, so subsequent calls to `multiFormData()` are fast and cannot fail.

The original casing of both the key and the name are preserved.

To iterate over all fields, use:

```zig
var it = req.multiFormData.iterator();
while (it.next()) |kv| {
  // kv.key
  // kv.value.value
  // kv.value.filename (optional)
}
```

Once this function is called, `req.formData()` will no longer work (because the body is assumed parsed).

Advance warning: This is one of the few methods that can modify the request in-place. For most people this won't be an issue, but if you use `req.body()` and `req.multiFormData()`, say to log the raw body, the content-disposition field names are escaped in-place. It's still safe to use `req.body()` but any  content-disposition name that was escaped will be a little off.

# zerv.Response
The following fields are the most useful:

* `status` - set the status code, by default, each response starts off with a 200 status code
* `content_type` - an zerv.ContentType enum value. This is a convenience and optimization over using the `res.header` function.
* `arena` - A fast thread-local buffer that fallsback to an ArenaAllocator, same as `req.arena`.

## Body
The simplest way to set a body is to set `res.body` to a `[]const u8`. **However** the provided value must remain valid until the body is written, which happens after the function exists or when `res.write()` is explicitly called.

## Dynamic Content
You can use the `res.arena` allocator to create dynamic content:

```zig
const query = try req.query();
const name = query.get("name") orelse "stranger";
res.body = try std.fmt.allocPrint(res.arena, "Hello {s}", .{name});
```

Memory allocated with `res.arena` will exist until the response is sent.

## io.Writer
`res.writer()` returns an `std.io.Writer`. Various types support writing to an io.Writer. For example, the built-in JSON stream writer can use this writer:

```zig
var ws = std.json.writeStream(res.writer(), 4);
try ws.beginObject();
try ws.objectField("name");
try ws.emitString(req.param("name").?);
try ws.endObject();
```

## JSON
The `res.json` function will set the content_type to `zerv.ContentType.JSON` and serialize the provided value using `std.json.stringify`. The 2nd argument to the json function is the `std.json.StringifyOptions` to pass to the `stringify` function.

This function uses `res.writer()` explained above.

## Header Value
Set header values using the `res.header(NAME, VALUE)` function:

```zig
res.header("Location", "/");
```

The header name and value are sent as provided. Both the name and value must remain valid until the response is sent, which will happen outside of the action. Dynamic names and/or values should be created and or dupe'd with `res.arena`. 

`res.headerOpts(NAME, VALUE, OPTS)` can be used to dupe the name and/or value:

```zig
try res.headerOpts("Location", location, .{.dupe_value = true});
```

`HeaderOpts` currently supports `dupe_name: bool` and `dupe_value: bool`, both default to `false`.

## Writing
By default, zerv will automatically flush your response. In more advance cases, you can use `res.write()` to explicitly flush it. This is useful in cases where you have resources that need to be freed/released only after the response is written. 
```

# Router
You get an instance of the router by calling `server.route(.{})`. Currently, the configuration takes a single parameter:

* `middlewares` - A list of middlewares to apply to each request. These middleware will be executed even for requests with no matching route (i.e. not found). An individual route can opt-out of these middleware, see the `middleware_strategy` route configuration.

You can use the `get`, `put`, `post`, `head`, `patch`, `trace`, `delete` or `options` method of the router to define a router. You can also use the special `all` method to add a route for all methods.

These functions can all `@panic` as they allocate memory. Each function has an equivalent `tryXYZ` variant which will return an error rather than panicking:

```zig
// this can panic if it fails to create the route
router.get("/", index, .{});

// this returns a !void (which you can try/catch)
router.tryGet("/", index, .{});
```

The 3rd parameter is a route configuration. It allows you to speficy a different `handler` and/or `dispatch` method and/or `middleware`.

```zig
// this can panic if it fails to create the route
router.get("/", index, .{
  .dispatcher = Handler.dispathAuth,
  .handler = &auth_handler,
  .middlewares = &.{cors_middleware},
});
```

## Configuration
The last parameter to the various `router` methods is a route configuration. In many cases, you'll probably use an empty configuration (`.{}`). The route configuration has three fields:

* `dispatcher` - The dispatch method to use. This overrides the default dispatcher, which is either zerv built-in dispatcher or [your handler's `dispatch` method](#custom-dispatch).
* `handler` - The handler instance to use. The default handler is the 3rd parameter passed to `Server(H).init` but you can override this on a route-per-route basis.
* `middlewares` - A list of [middlewares](#middlewares) to run. By default, no middlewares are run. By default, this list of middleware is appended to the list given to `server.route(.{.middlewares = .{....})`.
* `middleware_strategy` - How the given middleware should be merged with the global middlewares. Defaults to `.append`, can also be `.replace`.
* `data` - Arbitrary data (`*const anyopaque`) to make available to `req.route_data`. This must be a `const`.

You can specify a separate configuration for each route. To change the configuration for a group of routes, you have two options. The first, is to directly change the router's `handler`, `dispatcher` and `middlewares` field. Any subsequent routes will use these values:

```zig
var server = try zerv.Server(Handler).init(allocator, .{.port = 5882}, &handler);

var router = server.router(.{});

// Will use Handler.dispatch on the &handler instance passed to init
// No middleware
router.get("/route1", route1, .{});

router.dispatcher = Handler.dispathAuth;
// uses the new dispatcher
router.get("/route2", route2, .{}); 

router.handler = &Handler{.public = true};
// uses the new dispatcher + new handler
router.get("/route3", route3, .{.handler = Handler.dispathAuth});
```

This approach is error prone though. New routes need to be carefully added in the correct order so that the desired handler, dispatcher and middlewares are used.

A more scalable option is to use route groups.

## Groups
Defining a custom dispatcher or custom global data on each route can be tedious. Instead, consider using a router group:

```zig
var admin_routes = router.group("/admin", .{
  .handler = &auth_handler,
  .dispatcher = Handler.dispathAuth,
  .middlewares = &.{cors_middleware},
});
admin_routes.get("/users", listUsers, .{});
admin_routs.delete("/users/:id", deleteUsers, .{});
```

The first parameter to `group` is a prefix to prepend to each route in the group. An empty prefix is acceptable. Thus, route groups can be used to configure either a common prefix and/or a common configuration across multiple routes.

## Casing
You **must** use a lowercase route. You can use any casing with parameter names, as long as you use that same casing when getting the parameter.

## Parameters
Routing supports parameters, via `:CAPTURE_NAME`. The captured values are available via `req.params.get(name: []const u8) ?[]const u8`.  

## Glob
You can glob an individual path segment, or the entire path suffix. For a suffix glob, it is important that no trailing slash is present.

```zig
// prefer using a custom `notFound` handler than a global glob.
router.all("/*", not_found, .{});
router.get("/api/*/debug", .{})
```

When multiple globs are used, the most specific will be selected. E.g., give the following two routes:

```zig
router.get("/*", not_found, .{});
router.get("/info/*", any_info, .{})
```

A request for "/info/debug/all" will be routed to `any_info`, whereas a request for "/over/9000" will be routed to `not_found`.

## Limitations
The router has several limitations which might not get fixed. These specifically resolve around the interaction of globs, parameters and static path segments.

Given the following routes:

```zig
router.get("/:any/users", route1, .{});
router.get("/hello/users/test", route2, .{});
```

You would expect a request to "/hello/users" to be routed to `route1`. However, no route will be found. 

Globs interact similarly poorly with parameters and static path segments.

Resolving this issue requires keeping a stack (or visiting the routes recursively), in order to back-out of a dead-end and trying a different path.
This seems like an unnecessarily expensive thing to do, on each request, when, in my opinion, such route hierarchies are uncommon. 

# Middlewares
In general, use a [custom dispatch](#custom-dispatch) function to apply custom logic, such as logging, authentication and authorization. If you have complex route-specific logic, middleware can also be leveraged.

A middleware is a struct which exposes a nested `Config` type, a public `init` function and a public `execute` method. It can optionally define a `deinit` method. See the built-in [CORS middleware](https://github.com/pchchv/zerv/blob/master/src/middleware/Cors.zig) or the sample [logger middleware](https://github.com/pchchv/zerv/blob/master/example/middleware/Logger.zig) for examples.

A middleware instance is created using `server.middleware()` and can then be used with the router:

```zig
var server = try zerv.Server(void).init(allocator, .{.port = 5882}, {});

// the middleware method takes the struct name and its configuration
const cors = try server.middleware(zerv.middleware.Cors, .{
  .origin = "https://www.openmymind.net/",
});

// apply this middleware to all routes (unless the route 
// explicitly opts out)
var router = server.router(.{.middlewares = .{cors}});

// or we could add middleware on a route-per-route bassis
router.get("/v1/users", .{.middlewares = &.{cors}});

// by default, middlewares on a route are appended to the global middlewares
// we can replace them instead by specifying a middleware_strategy
router.get("/v1/metrics", .{.middlewares = &.{cors}, .middleware_strategy = .replace});
```

## Cors
zerv comes with a built-in CORS middleware: `zerv.middlewares.Cors`. Its configuration is:

* `origin: []const u8`
* `headers: ?[]const u8 = null`
* `methods: ?[]const u8 = null`
* `max_age: ?[]const u8 = null`

The CORS middleware will include a `Access-Control-Allow-Origin: $origin` to every request. For an OPTIONS request where the `sec-fetch-mode` is set to `cors, the `Access-Control-Allow-Headers`, `Access-Control-Allow-Methods` and `Access-Control-Max-Age` response headers will optionally be set based on the configuration.


# Configuration
The second parameter given to `Server(H).init` is an `zerv.Config`. When running in <a href=#blocking-mode>blocking mode</a> (e.g. on Windows) a few of these behave slightly, but not drastically, different.

There are many configuration options. 

`thread_pool.buffer_size` is the single most important value to tweak. Usage of `req.arena`, `res.arena`, `res.writer()` and `res.json()` all use a fallback allocator which first uses a fast thread-local buffer and then an underlying arena. The total memory this will require is `thread_pool.count * thread_pool.buffer_size`. Since `thread_pool.count` is usually small, a large `buffer_size` is reasonable.

`request.buffer_size` must be large enough to fit the request header. Any extra space might be used to read the body. However, there can be up to `workers.count * workers.max_conn` pending requests, so a large `request.buffer_size` can take up a lot of memory. Instead, consider keeping `request.buffer_size` only large enough for the header (plus a bit of overhead for decoding URL-escape values) and set `workers.large_buffer_size` to a reasonable size for your incoming request bodies. This will take `workers.count * workers.large_buffer_count * workers.large_buffer_size` memory. 

Buffers for request bodies larger than `workers.large_buffer_size` but smaller than `request.max_body_size` will be dynamic allocated.

In addition to a bit of overhead, at a minimum, zerv will use:

```zig
(thread_pool.count * thread_pool.buffer_size) +
(workers.count * workers.large_buffer_count * workers.large_buffer_size) +
(workers.count * workers.min_conn * request.buffer_size)
```

Possible values, along with their default, are:

```zig
try zerv.listen(allocator, &router, .{
    // Port to listen on
    .port = 5882, 

    // Interface address to bind to
    .address = "127.0.0.1",

    // unix socket to listen on (mutually exclusive with host&port)
    .unix_path = null,

    // configure the workers which are responsible for:
    // 1 - accepting connections
    // 2 - reading and parsing requests
    // 3 - passing requests to the thread pool
    .workers = .{
        // Number of worker threads
        // (blocking mode: handled differently)
        .count = 2,

        // Maximum number of concurrent connection each worker can handle
        // (blocking mode: currently ignored)
        .max_conn = 500,

        // Minimum number of connection states each worker should maintain
        // (blocking mode: currently ignored)
        .min_conn = 32,

        // A pool of larger buffers that can be used for any data larger than configured
        // static buffers. For example, if response headers don't fit in in 
        // $response.header_buffer_size, a buffer will be pulled from here.
        // This is per-worker. 
        .large_buffer_count = 16,

        // The size of each large buffer.
        .large_buffer_size = 65536,

        // Size of bytes retained for the connection arena between use. This will
        // result in up to `count * min_conn * retain_allocated_bytes` of memory usage.
        .retain_allocated_bytes = 4096,
    },

    // configures the threadpool which processes requests. The threadpool is 
    // where your application code runs.
    .thread_pool = .{
        // Number threads. If you're handlers are doing a lot of i/o, a higher
        // number might provide better throughput
        // (blocking mode: handled differently)
        .count = 4,

        // The maximum number of pending requests that the thread pool will accept
        // This applies back pressure to the above workers and ensures that, under load
        // pending requests get precedence over processing new requests.
        .backlog = 500,

        // Size of the static buffer to give each thread. Memory usage will be 
        // `count * buffer_size`. If you're making heavy use of either `req.arena` or
        // `res.arena`, this is likely the single easiest way to gain performance. 
        .buffer_size = 8192,
    },

    // options for tweaking request processing
    .request = .{
        // Maximum body size that we'll process. We can allocate up 
        // to this much memory per request for the body. Internally, we might
        // keep this memory around for a number of requests as an optimization.
        .max_body_size: usize = 1_048_576,

        // This memory is allocated upfront. The request header _must_ fit into
        // this space, else the request will be rejected.
        .buffer_size: usize = 4_096,

        // Maximum number of headers to accept. 
        // Additional headers will be silently ignored.
        .max_header_count: usize = 32,

        // Maximum number of URL parameters to accept.
        // Additional parameters will be silently ignored.
        .max_param_count: usize = 10,

        // Maximum number of query string parameters to accept.
        // Additional parameters will be silently ignored.
        .max_query_count: usize = 32,

        // Maximum number of x-www-form-urlencoded fields to support.
        // Additional parameters will be silently ignored. This must be
        // set to a value greater than 0 (the default) if you're going
        // to use the req.formData() method.
        .max_form_count: usize = 0,

        // Maximum number of multipart/form-data fields to support.
        // Additional parameters will be silently ignored. This must be
        // set to a value greater than 0 (the default) if you're going
        // to use the req.multiFormData() method.
        .max_multiform_count: usize = 0,
    },

    // options for tweaking response object
    .response = .{
        // The maximum number of headers to accept. 
        // Additional headers will be silently ignored.
        .max_header_count: usize = 16,
    },

    .timeout = .{
        // Time in seconds that keepalive connections will be kept alive while inactive
        .keepalive = null,

        // Time in seconds that a connection has to send a complete request
        .request = null

        // Maximum number of a requests allowed on a single keepalive connection
        .request_count = null,
    },
    .websocket = .{
        // refer to https://github.com/pchchv/websocket.zig#config
        max_message_size: ?usize = null,
        small_buffer_size: ?usize = null,
        small_buffer_pool: ?usize = null,
        large_buffer_size: ?usize = null,
        large_buffer_pool: ?u16 = null,
    },
});
```

## Blocking Mode
kqueue (BSD, MacOS) or epoll (Linux) are used on supported platforms. On all other platforms (most notably Windows), a more naive thread-per-connection with blocking sockets is used.

The comptime-safe, `zerv.blockingMode() bool` function can be called to determine which mode zerv is running in (when it returns `true`, then you're running the simpler blocking mode).

While you should always run zerv behind a reverse proxy, it's particularly important to do so in blocking mode due to the ease with which external connections can DOS the server.

In blocking mode, `config.workers.count` is hard-coded to 1. (This worker does considerably less work than the non-blocking workers). If `config.workers.count` is > 1, than those extra workers will go towards `config.thread_pool.count`. In other words:

In non-blocking mode, if `config.workers.count = 2` and `config.thread_pool.count = 4`, then you'll have 6 threads: 2 threads that read+parse requests and send replies, and 4 threads to execute application code.

In blocking mode, the same config will also use 6 threads, but there will only be: 1 thread that accepts connections, and 5 threads to read+parse requests, send replies and execute application code.

The goal is for the same configuration to result in the same # of threads regardless of the mode, and to have more thread_pool threads in blocking mode since they do more work.

In blocking mode, `config.workers.large_buffer_count` defaults to the size of the thread pool.

In blocking mode, `config.workers.max_conn` and `config.workers.min_conn` are ignored. The maximum number of connections is simply the size of the thread_pool.

If you aren't using a reverse proxy, you should always set the `config.timeout.request`, `config.timeout.keepalive` and `config.timeout.request_count` settings. In blocking mode, consider using conservative values: say 5/5/5 (5 second request timeout, 5 second keepalive timeout, and 5 keepalive count). You can monitor the `zerv_timeout_active` metric to see if the request timeout is too low.

## Timeouts
The configuration settings under the `timeouts` section are designed to help protect the system against basic DOS attacks (say, by connecting and not sending data). However it is recommended that you leave these null (disabled) and use the appropriate timeout in your reverse proxy (e.g. NGINX). 

The `timeout.request` is the time, in seconds, that a connection has to send a complete request. The `timeout.keepalive` is the time, in second, that a connection can stay connected without sending a request (after the initial request has been sent).

The connection alternates between these two timeouts. It starts with a timeout of `timeout.request` and after the response is sent and the connection is placed in the "keepalive list", switches to the `timeout.keepalive`. When new data is received, it switches back to `timeout.request`. When `null`, both timeouts default to 2_147_483_647 seconds (so not completely disabled, but close enough).

The `timeout.request_count` is the number of individual requests allowed within a single keepalive session. This protects against a client consuming the connection by sending unlimited meaningless but valid HTTP requests.

When the three are combined, it should be difficult for a problematic client to stay connected indefinitely.

If you're running zerv on Windows (or, more generally, where <code>zerv.blockingMode()</code> returns true), please <a href="#blocking-mode">read the section</a> as this mode of operation is more susceptible to DOS.

# Metrics
A few basic metrics are collected using [metrics.zig](https://github.com/pchchv/metrics.zig), a prometheus-compatible library. These can be written to an `std.io.Writer` using `try zerv.writeMetrics(writer)`. As an example:

```zig
pub fn metrics(_: *zerv.Request, res: *zerv.Response) !void {
    const writer = res.writer();
    try zerv.writeMetrics(writer);

    // if we were also using pg.zig 
    // try pg.writeMetrics(writer);
}
```

Since zerv does not provide any authorization, care should be taken before exposing this. 

The metrics are:

* `zerv_connections` - counts each TCP connection
* `zerv_requests` - counts each request (should  be >= zerv_connections due to keepalive)
* `zerv_timeout_active` - counts each time an "active" connection is timed out. An "active" connection is one that has (a) just connected or (b) started to send bytes. The timeout is controlled by the `timeout.request` configuration.
* `zerv_timeout_keepalive` - counts each time an "keepalive" connection is timed out. A "keepalive" connection has already received at least 1 response and the server is waiting for a new request. The timeout is controlled by the `timeout.keepalive` configuration.
* `zerv_alloc_buffer_empty` - counts number of bytes allocated due to the large buffer pool being empty. This may indicate that `workers.large_buffer_count` should be larger.
* `zerv_alloc_buffer_large` - counts number of bytes allocated due to the large buffer pool being too small. This may indicate that `workers.large_buffer_size` should be larger.
* `zerv_alloc_unescape` - counts number of bytes allocated due to unescaping query or form parameters. This may indicate that `request.buffer_size` should be larger.
* `zerv_internal_error` - counts number of unexpected errors within zerv. Such errors normally result in the connection being abruptly closed. For example, a failing syscall to epoll/kqueue would increment this counter.
* `zerv_invalid_request` - counts number of requests which zerv could not parse (where the request is invalid).
* `zerv_header_too_big` - counts the number of requests which zerv rejects due to a header being too big (does not fit in `request.buffer_size` config).
* `zerv_body_too_big` - counts the number of requests which zerv rejects due to a body being too big (is larger than `request.max_body_size` config).

# Testing
The `zerv.testing` namespace exists to help application developers setup an `*zerv.Request` and assert an `*zerv.Response`.

Imagine we have the following partial action:

```zig
fn search(req: *zerv.Request, res: *zerv.Response) !void {
    const query = try req.query();
    const search = query.get("search") orelse return missingParameter(res, "search");

    // TODO ...
}

fn missingParameter(res: *zerv.Response, parameter: []const u8) !void {
    res.status = 400;
    return res.json(.{.@"error" = "missing parameter", .parameter = parameter}, .{});
}
```

We can test the above error case like so:

```zig
const ht = @import("zerv").testing;

test "search: missing parameter" {
    // init takes the same Configuration used when creating the real server
    // but only the config.request and config.response settings have any impact
    var web_test = ht.init(.{});
    defer web_test.deinit();

    try search(web_test.req, web_test.res);
    try web_test.expectStatus(400);
    try web_test.expectJson(.{.@"error" = "missing parameter", .parameter = "search"});
}
```

## Building the test Request
The testing structure returns from <code>zerv.testing.init</code> exposes helper functions to set param, query and query values as well as the body:

```zig
var web_test = ht.init(.{});
defer web_test.deinit();

web_test.param("id", "99382");
web_test.query("search", "tea");
web_test.header("Authorization", "admin");

web_test.body("over 9000!");
// OR
web_test.json(.{.over = 9000});
// OR 
// This requires ht.init(.{.request = .{.max_form_count = 10}})
web_test.form(.{.over = "9000"});

// at this point, web_test.req has a param value, a query string value, a header value and a body.
```

As an alternative to the `query` function, the full URL can also be set. If you use `query` AND `url`, the query parameters of the URL will be ignored:

```zig
web_test.url("/power?over=9000");
```

## Asserting the Response
There are various methods to assert the response:

```zig
try web_test.expectStatus(200);
try web_test.expectHeader("Location", "/");
try web_test.expectHeader("Location", "/");
try web_test.expectBody("{\"over\":9000}");
```

If the expected body is in JSON, there are two helpers available. First, to assert the entire JSON body, you can use `expectJson`:

```zig
try web_test.expectJson(.{.over = 9000});
```

Or, you can retrieve a `std.json.Value` object by calling `getJson`:

```zig
const json = try web_test.getJson();
try std.testing.expectEqual(@as(i64, 9000), json.Object.get("over").?.Integer);
```

For more advanced validation, use the `parseResponse` function to return a structure representing the parsed response:

```zig
const res = try web_test.parsedResponse();
try std.testing.expectEqual(@as(u16, 200), res.status);
// use res.body for a []const u8  
// use res.headers for a std.StringHashMap([]const u8)
// use res.raw for the full raw response
```

# HTTP Compliance
This implementation may never be fully HTTP/1.1 compliant, as it is built with the assumption that it will sit behind a reverse proxy that is tolerant of non-compliant upstreams (e.g. nginx). (One example I know of is that the server doesn't include the mandatory Date header in the response.)

# Server Side Events
Server Side Events can be enabled by calling `res.startEventStream()`. This method takes an arbitrary context and a function pointer. The provided function will be executed in a new thread, receiving the provided context and an `std.net.Stream`. Headers can be added (via `res.headers.add`) before calling `startEventStream()`. `res.body` must not be set (directly or indirectly).

Calling `startEventStream()` automatically sets the `Content-Type`, `Cache-Control` and `Connection` header.

```zig
fn handler(_: *Request, res: *Response) !void {
    try res.startEventStream(StreamContext{}, StreamContext.handle);
}

const StreamContext = struct {
    fn handle(self: StreamContext, stream: std.net.Stream) void {
        while (true) {
            // some event loop
            stream.writeAll("event: ....") catch return;
        }
    }
}
```

# Websocket
zerv integrates with [https://github.com/pchchv/websocket.zig](https://github.com/pchchv/websocket.zig) by calling `zerv.upgradeWebsocket()`. First, your handler must have a `WebsocketHandler` declaration which is the WebSocket handler type used by `websocket.Server(H)`.

```zig
const websocket = zerv.websocket;

const Handler = struct {
  // App-specific data you want to pass when initializing
  // your WebSocketHandler
  const WebsocketContext = struct {

  };

  // See the websocket.zig documentation. But essentially this is your
  // Application's wrapper around 1 websocket connection
  pub const WebsocketHandler = struct {
    conn: *websocket.Conn,

    // ctx is arbitrary data you passs to zerv.upgradeWebsocket
    pub fn init(conn: *websocket.Conn, _: WebsocketContext) {
      return .{
        .conn =  conn,
      }
    }

    // echo back
    pub fn clientMessage(self: *WebsocketHandler, data: []const u8) !void {
        try self.conn.write(data);
    }
  }  
};
```

With this in place, you can call zerv.upgradeWebsocket() within an action:

```zig
fn ws(req: *zerv.Request, res: *zerv.Response) !void {
  if (try zerv.upgradeWebsocket(WebsocketHandler, req, res, WebsocketContext{}) == false) {
  // this was not a valid websocket handshake request
  // you should probably return with an error
  res.status = 400;
  res.body = "invalid websocket handshake";
  return;
  }
  // Do not use `res` from this point on
}
```

In websocket.zig, `init` is passed a `websocket.Handshake`. This is not the case with the zerv integration - you are expected to do any necessary validation of the request in the action.

It is an undefined behavior if `Handler.WebsocketHandler` is not the same type passed to `zerv.upgradeWebsocket`.

# Bare Metal Zig on STM32

This is about using [Zig](https://ziglang.org) alone to directly program boards based on STM32F103xx MCU, such as "Blue
Pill" clones of Maple Mini.

## Requirements

- A Blue Pill board or similar, see [here](https://stm32-base.org/boards/STM32F103C8T6-Blue-Pill.html) for general and
  physical info.

- [Zig](https://ziglang.org/download/) to build our examples. (I used version 0.13.0 here.)

- [ST-Link Tools](https://github.com/stlink-org/stlink) to flash them.

## Docs

- [Blue Pill Schematic](https://stm32-base.org/assets/pdf/boards/original-schematic-STM32F103C8T6-Blue_Pill.pdf).

- [STM32 Cortex®-M3 Programming Manual](https://www.st.com/resource/en/programming_manual/pm0056-stm32f10xxx20xxx21xxxl1xxxx-cortexm3-programming-manual-stmicroelectronics.pdf) for general info on Cortex-M3.

- [STM32F10x Reference Manual](https://www.st.com/resource/en/reference_manual/cd00171190-stm32f101xx-stm32f102xx-stm32f103xx-stm32f105xx-and-stm32f107xx-advanced-arm-based-32-bit-mcus-stmicroelectronics.pdf) to know how to program all available peripherals.

- [STM32F103x8 Datasheet](https://www.st.com/resource/en/datasheet/stm32f103c8.pdf) to know what exactly is available
  in our MCU as the above reference manual describes the whole family.

- [Info on Linker Scripts](https://ftp.gnu.org/old-gnu/Manuals/ld-2.9.1/html_chapter/ld_3.html) to be able to describe memory layout to the linker.

## Target

One of the cool things about Zig is that (thanks to LLVM) it can compile for many architectures out of the box and yet
manages to keep its MacOS package size under 50MB without any external dependencies!

Zig expects its `-target` command line switch to be a dash-separated triple identifying architecture, operating system
and ABI (application binary interface) of the target system. See the whole list by running:

    zig targets | less

Our architecture is ARM, we don't have any OS and we don't care about any particular ABI, so we are going to use
`arm-freestanding-none` as our `-target`.

Another command line switch, `-mcpu`, should be used to specify the processor to generate the code for. STM32F103xx is
based on Cortext-M3, so consulting the list of supported targets the most logical choice seemed to be `cortex_m3`. I am
getting build errors when using one however (something about an instruction in `IT` block), so I decided to step back
to `cortex_m23` that seems to be a subset of Cortext-M3 instruction-wise, missing exactly the `IT` instruction. (I
don't expect the compiler to use "TrustZone" security extensions. We could also use `cortex_m0` to be 100% sure it
won't generate something unsupported.)

Before we go to the remaining compiler settings let's type in some code first. Let's make the classic "Blink" example toggling the on-board LED (see `v0/main.zig`). It's not going to be nice, but we'll improve it later.

## Version 0

Looking at the Blue Pill Schematic we see that the LED is attached to PC13 of the MCU which can be controlled via port 13 of GPIO bank C. GPIO and the corresponding registers are described in Chapter 9 of the Reference Manual, while the base address of bank C, `0x4001_1000`, can be found in the STM32F103x8 Datasheet. 

Before we can use the GPIO bank C however we need to enable it via one of the Reset and Clock Control (RCC) registers (base `0x4002_1000`), see chapter 7.3. GPIO bank C is controlled by bit 4 of `RCC_APB2ENR`, offset `0x18`:

```zig
reg(0x4002_1000 + 0x18).* |= 1 << 4;
```

Where `reg()` is a simple wrapper that gets us a `volatile` pointer, which we need when working with memory mapped registers for Zig's optimizer to not try removing or reorder our reads/writes.

```zig
fn reg(comptime address: u32) *volatile u32 {
    return @ptrFromInt(address);
}
```

Before we can start toggling port 13 however we need to configure it as output via `GPIOx_CRH` register (offset `0x04`, see chapter 9.2.2). Each nibble in this register is responsible for configuration of ports 8-15:

```zig
reg(0x4001_1000 + 0x04).* |= 0b01_10 << (4 * (13 - 8)); // Relying on the reset value being 0b01_00.
```

We'll be using `GPIOx_BSRR` register (offset `0x10` from the base, see chapter 9.2.5) to control the output state of our port. Setting bits 0-15 here sets the output on ports 0-15 to 1, while setting bits 16-32 *resets* the output on the same ports. (This register is more convenient than more traditional `GPIOx_ODR`, because there is no need to read its current state to modify a single bit.)

```zig
const GPIOC_BSRR = reg(0x4001_1000 + 0x10);
while (true) {
    GPIOC_BSRR.* = 1 << (13 + 16);
    delay(50);
    GPIOC_BSRR.* = 1 << 13;
    delay(950);
}
```

To implement `delay()` we'll just do something in a long loop. (We'll return to better implementation in the next version of the example.)

```zig
fn delay_ticks(ticks: u32) void {
    var i = ticks;
    while (i > 0) {
        // Reading any location to prevent the loop from being optimized out.
        _ = reg(0x2000_0000).*;
        i -= 1;
    }
}
```

To calculate the number of ticks we need to iterate to get a millisecond delay we need to know that after reset our CPU runs approximately at 8MHz and that every iteration in the above loop takes 6 CPU cycles (more on this below):

```zig
fn delay(comptime ms: u32) void {
    delay_ticks(ms * 8_000 / 6);
}
```

## Linker Script

OK, now when we have a basic program (see `v0/main.zig`) we can try to compile it:

    zig build-exe -target arm-freestanding-none -mcpu cortex_m23 -O ReleaseSmall -femit-asm main.zig

The extra `-femit-asm` flag makes Zig produce assembly output which is handy when examining our code. For example, this is how we can calculate how many CPU clock cycles `delay_ticks()` spends per tick (comments added by me using info on [this page](https://developer.arm.com/documentation/ddi0337/e/Instruction-Timing/Processor-instruction-timings)):

```asm
main.delay_ticks:           ; r0 contains the number of ticks already.
    movs    r1, #1
    lsls    r1, r1, #29     ; (1 << 29) is this 0x20000000 address we are reading from below.
.LBB1_1:
    cbz r0, .LBB1_3         ; 1 cycle, branch not taken. (Jump out of the loop if tick counter in r0 is zero.)
    ldr r2, [r1]            ; 2 cycles. (Our fake read.)
    subs    r0, r0, #1      ; 1 cycle. (Decrement the tick counter in r0.)
    b   .LBB1_1             ; 2 cycles, branch is taken. (Repeat the loop.)
.LBB1_3:
    bx  lr                  ; Return from the function.
```

Speaking of assembly, we could also disassemble the output file directly with `objdump -d main`, but it might be harder to see what's going on, here is the same `delay_ticks()` function:

    20130: 2101             movs    r1, #1
    20132: 0749             lsls    r1, r1, #29
    20134: b110             cbz r0, 0x2013c <.text+0x50> @ imm = #4
    20136: 680a             ldr r2, [r1]
    20138: 1e40             subs    r0, r0, #1
    2013a: e7fb             b   0x20134 <.text+0x48>    @ imm = #-10
    2013c: 4770             bx  lr

Another thing that we can see with `objdump` is that our code starts at address `000200ec` which is quite wrong for our MCU where flash memory begins at `0x08000000`:

    main:   file format elf32-littlearm

    Disassembly of section .text:

    000200ec <.text>:
       200ec: 480c          ldr r0, [pc, #48]           @ 0x20120 <.text+0x34>
       200ee: 6801          ldr r1, [r0]
       200f0: 2210          movs    r2, #16
    ...

Well, this is logical because Zig does not really know much about our MCU. We need to help it by writing a "linker script". The official documentation on the topic mentioned above is easy to read and actual scripts are fairly self-explanatory.

The first thing we do in our script (`v0/bluepill.ld`) is describing relevant memory regions, which is quite simple in our case as we have 128K of flash memory starting at `0x08000000` and 20K of RAM starting at `0x20000000` (see chapter 4 in the Datasheet):

    MEMORY {
        flash (rx)  : o = 0x08000000, l = 128K
        sram (rw)   : o = 0x20000000, l = 20K
    }

(The names of the regions can be arbitrary here, the linker does not know what the "flash" is.)

The next part of the script tells what should be placed into the flash memory:

    SECTIONS {
        .text : {
            ...
        } >flash

We cannot tell it to begin filling with the code from the start as the first word has to be the value of the main stack pointer (MSP), as per chapter 2.1.2 of the Programming Manual:

> On reset, the processor loads the MSP with the value from address 0x00000000.

(The address is from the start of the flash, `0x08000000` in our case.)

Next go interrupt vectors (see table 63 in the Reference Manual) of which we are only interested in the first one, Reset, as we don't use interrupts just yet:

    .text : {
        /* The initial value of SP, past the end of RAM. */
        LONG(ORIGIN(sram) + LENGTH(sram))
        /* Reset vector. */
        LONG(_start)
        /* We should put a bunch of other vectors here, but since none are used yet we can use the space. */
        /* So now goes our code. */
        *(.text)
        /* Then read-only data. */
        *(.rodata.*) 
        *(.rodata) 
    } >flash

Next we tell that our writable data (static variables) is expected in RAM. We don't have such variables in our simple example yet, but that'll be handy later.

    .bss : { 
        *(.bss) 
    } >sram

And finally we exclude a few extra code segments that otherwise would increase the size of our binary:

    /DISCARD/ : { 
        /* I don't want to keep sections needed only when printing stack traces. */
        *(.ARM.*)
    }

Let's compile using our linker script now:

    zig build-exe -target arm-freestanding-none -mcpu cortex_m23 -femit-asm -O ReleaseSmall --script bluepill.ld main.zig

Disassembling with `objdump` shows that the addresses are correct now:

    main:   file format elf32-littlearm

    Disassembly of section .text:

    08000000 <.text>:
     8000000: 20005000      andhs   r5, r0, r0
     8000004: 08000009      stmdaeq r0, {r0, r3}
     8000008: 6801480c      stmdavs r1, {r2, r3, r11, lr}
    ...

The first word appears to be the desired stack pointer just beyond the RAM followed by the Reset vector pointing to the next word. The number is even to indicate Thumb mode. Let's add `--mcpu=cortex-m23` to force Thumb mode:

    08000000 <.text>:
     8000000: 5000          str r0, [r0, r0]
     8000002: 2000          movs    r0, #0
     8000004: 0009          movs    r1, r1
     8000006: 0800          lsrs    r0, r0, #32
     8000008: 480c          ldr r0, [pc, #48]           @ 0x800003c <.text+0x3c>
     800000a: 6801          ldr r1, [r0]
     800000c: 2210          movs    r2, #16
     ...

OK, now the part starting at `0x8000008` looks like the code in our `.s` file.

## Flashing

We'll be using `st-flash` utility which expects either a raw binary with the starting address passes separately or an Intel hex file that already contains addresses. Let's use the latter by converting our build to `.hex` with Zig:

    zig objcopy -O hex main main.hex

Flashing is then as simple as:

    st-flash --reset --format ihex write main.hex 

You'll see something like this and your LED will hopefully start blinking every second:

    st-flash 1.8.0
    2024-08-18T22:01:38 INFO common.c: STM32F1xx_MD: 20 KiB SRAM, 128 KiB flash in at least 1 KiB pages.
    2024-08-18T22:01:38 INFO common_flash.c: Attempting to write 90 (0x5a) bytes to stm32 address: 134217728 (0x8000000)
    -> Flash page at 0x8000000 erased (size: 0x400)
    2024-08-18T22:01:38 INFO flash_loader.c: Starting Flash write for VL/F0/F3/F1_XL
    2024-08-18T22:01:38 INFO flash_loader.c: Successfully loaded flash loader in sram
    2024-08-18T22:01:38 INFO flash_loader.c: Clear DFSR
      1/1   pages written
    2024-08-18T22:01:38 INFO common_flash.c: Starting verification of write complete
    2024-08-18T22:01:38 INFO common_flash.c: Flash written and verified! jolly good!

Also, as you can see our code is just 90 bytes, which is quite nice given all the required setup instructions.

## V1

Now let's improve the example showing some power of Zig:

```zig
export fn _start() noreturn {
    const bankC = GPIOBank(.C);
    bankC.init();

    const led = bankC.port(13);
    led.setOutput(.openDrain, .max2MHz);

    while (true) {
        led.reset();
        delay(50);
        led.set();
        delay(950);
    }
}
```

The `GPIOBank` is an abstraction that is more readable, more reusable (we can use all banks/ports) but does not add any overhead as all the selection of the bank and port happen at compile time. Our program is 94 bytes now, which is just 4 bytes larger only because we are not relying on the reset values when writing to `GPIOC_CRH` as we want to change pin configuration at runtime:

```zig
pub fn GPIOBank(comptime bank: GPIOBankIndex) type {
    return struct {
        /* ... */
        pub fn port(comptime pin: u4) type {
            return struct {
                fn reg(comptime offset: u32) *volatile u32 {
                    return @ptrFromInt(switch (bank) {
                        .A => 0x4001_0800,
                        .B => 0x4001_0C00,
                        .C => 0x4001_1000,
                        .D => 0x4001_1400,
                        .E => 0x4001_1800,
                    } + offset);
                }

                fn setModeBits(comptime bits: u32) void {
                    const CRx = reg(if (pin >= 8) 0x04 else 0x00);
                    const shift = 4 * @as(u8, if (pin >= 8) pin - 8 else pin);
                    CRx.* = CRx.* & ~(@as(u32, 0xF) << shift) | (bits << shift);
                }

                const BSRR = reg(0x10);

                pub fn set() void {
                    BSRR.* = 1 << pin;
                }
                /* ... */
            };
        }
    };
}
```

As you can see `reg()` depends on the bank, but since both `bank` and `pin` are `comptime`, thus both `GPIOx_CRx` (L or H) and `GPIOx_BSRR` are picked at compile time as well and we always get highly optimized code.

## V2

Here we are adding a `SysTick` timer for a better `delay()` along with `USART` to say the actual `Hello`. (I've moved all helpers into a module called `z41` here.)

Our binary is `792` bytes now, or `314` if we completely remove the line with `usart.writer.print`, and `432` if we keep it but don't output the number. In other words, the use of `std.fmt` adds overhead only when specifiers are actually used, something that would be hard to achieve with a `printf()`-style C/C++ function.

```zig
const std = @import("std");
const z41 = @import("z41");

export fn _start() noreturn {
    const rcc = z41.RCC(.internalRC);
    rcc.init();

    const SysTick = z41.SysTick(rcc.SYSCLK, 50);
    SysTick.init();

    const led = z41.GPIO(rcc, .C).port(13);
    led.Bank.init();
    led.setOutput(.openDrain, .max2MHz);

    const usart = z41.USART(rcc, .usart1);
    usart.init(115200);

    usart.writeBytes("\nHello! It's V2\n\n");

    while (true) {
        led.reset();
        SysTick.delay(50);

        led.set();
        SysTick.delay(950);

        try usart.writer.print("\rUptime: {}s", .{SysTick.milliseconds() / 1000});
    }
}
```

### RegisterSet

I've added `RegisterSet` under the hood to help with definition of hardware registers. It's similar to this `reg()` helper from `v0`, but allows using structs as well. For example, this is how `STK_CTRL` is described in `SysTick` (you should appreciate Zig allowing anonymous enums like here in `CLKSOURCE`):

```zig
const STK_CTRL = regs.at(0, packed struct(u32) {
    /// Counter enable.
    ENABLE: bool,
    TICKINT: bool,
    CLKSOURCE: enum(u1) {
        /// AHB/8.
        AHB_8 = 0,
        /// Processor clock (AHB).
        AHB = 1,
    },
    _r1: u13 = 0,
    COUNTFLAG: bool = false,
    _r2: u15 = 0,
});
```

You can still use raw `u32` registers where needed:

```zig
const STK_LOAD = regs.at(4, u32);
```

The helper checks the type you pass to make sure it's `u32` or `u32`-backed `packed struct`:

```zig
pub fn at(comptime offset: u32, comptime reg_type: type) *volatile reg_type {
    const valid = switch (@typeInfo(reg_type)) {
        .Struct => |s| switch (s.layout) {
            .@"packed" => s.backing_integer == u32,
            else => false,
        },
        .Int => |i| i.bits == 32,
        else => false,
    };
    if (!valid) {
        @compileError("Expected `reg_type` to be u32 or a packed struct backed by u32");
    }
    return @ptrFromInt(base + offset);
}
```

### SysTick

A `SysTick` timer is described in the chapter 4.5 of the Programming Manual and is something common to all processors based on Cortex®-M3. It's a simple counter that is decremented on every (or every 8ths) CPU clock cycle and generates an interrupt when it reaches zero. It can be used to implement a notion of system time (e.g. milliseconds since system start) along with better delays, where we don't have to rely on how exactly our code is compiled.

We need to be able to handle interrupts for this helper and this is where our linker script needs to be changed. The handler itself is simple:

```zig
pub fn SysTick(comptime cpuFreq: u32, comptime msPerTick: u32) type {
    return struct {
        export fn SysTick_Vector() void {
            total_ms +%= msPerTick;
        }

        var total_ms: u32 = undefined;
        ...
```

It needs to be `export`ed for our linker script to place a pointer to it into an appropriate location. (Note that the export only happens when `SysTick` is used, something that would be hard to achieve in C/C++ without macros.) 

Other than `export` no other attributes are needed here thanks to the clever way interrupts ("exceptions") are handled (see chapter 2.3.7 in the Programming Manual):

- registers `r0`-`r3` are automatically pushed to the stack along with flags when an interrupt occurs, while remaining registers are already expected to be preserved by the compiler even in regular functions;

- unlike other architectures no special "return from interrupt" instruction is needed, because the return address in `LR` register is set to a special value that any return from function (`bx lr`) will be recognized as a return from an interrupt restoring `r0`-`r3`, etc.

So we need to add a pointer to our handler into the interrupt vector table at the start of our code (see table 63 in the Reference Manual again):

    .text : {
        ...
    	LONG(_start);

        /* We don't use any interrupt vectors before SysTick, so let's just fill.  */
        FILL(0); . = ADDR(.text) + 0x003C;

        LONG(DEFINED(SysTick_Vector) ? SysTick_Vector : 0xDEAD);

    	/* Other vectors follow, but since we are not using them we can just start our code earlier. */
        ...

Note the use of `DEFINED`: it allows correct linking even when the target program does not need the `SysTick` timer. (By the way, the use of `0xDEAD` for undefined handlers is temporary here, a central "panic" handler halting the MCU would be a better option eventually.)

### `build.zig`

I've been using a simple shell script to build and flash the first 2 examples:

```bash
#!/bin/sh -e
zig build-exe \
	-target arm-freestanding-none \
	-mcpu cortex_m23 \
	-femit-asm \
	-O ReleaseSmall \
	--script bluepill.ld \
	main.zig
zig objcopy -O hex main main.hex
rm main main.o
st-flash --reset --format ihex write main.hex 
```

However in this one we want to be able to pull our helpers from a "module" in `./lib`. This still could be described in a shell script of course, but I also was curious about Zig's build system, so I've added `build.zig`.

Now the example can be compiled with `zig build` or flashed with `zig build flash`.

